import * as T from 'three';
import {compactStaticGeometry as compact} from './compact-static.js';
import {createBoatView} from './boat-view.js';
import {buildDock} from './dock-view.js';
import {BOAT_ENDPOINTS} from './layout.js';
import {HARBOR_FRAME} from '../world/main-island-layout.js';
import {disposeToyTree} from '../world/toy-kit.js';

function farBoat(){const root=new T.Group();root.name='harbor.boat.far';const materials=['#729b9f','#c2a788','#efdfbb'].map(color=>new T.MeshStandardMaterial({color,roughness:.95})),shape=new T.Shape(),outline=[[-1.48,2.35],[-1.48,-1.5],...Array.from({length:9},(_,i)=>{const a=Math.PI-i*Math.PI/8;return[1.48*Math.cos(a),-1.5-1.35*Math.sin(a)];}),[1.48,2.35]];outline.forEach(([x,z],i)=>i?shape.lineTo(x,-z):shape.moveTo(x,-z));shape.closePath();const geo=new T.ExtrudeGeometry(shape,{depth:.58,bevelEnabled:false});geo.rotateX(-Math.PI/2);geo.translate(0,-.18,0);root.add(new T.Mesh(geo,materials[0]));const deck=new T.Mesh(new T.ShapeGeometry(shape),materials[1]);deck.rotation.x=-Math.PI/2;deck.position.y=.401;root.add(deck);const box=(w,h,d,mat,x,y,z)=>{const mesh=new T.Mesh(new T.BoxGeometry(w,h,d),materials[mat]);mesh.position.set(x,y,z);root.add(mesh);};for(const x of[-1.42,1.42]){box(.16,.55,3.85,0,x,.38,.425);box(.20,.10,3.90,2,x,.695,.425);}box(1.8,.16,.9,2,0,.6,-.045);box(1.85,.53,.12,0,0,1.02,-.61);box(1.9,.05,1.5,2,0,.09,3.25);compact(root);return root;}
function parkedBoat(){const root=new T.Group();root.name='harbor.parked-boat';const far=farBoat();root.add(far);let near=null,alive=true,pins=0,shown=true,frame={};const ensure=()=>{if(!alive)return false;if(!near){near=createBoatView();near.root.name='harbor.boat.near';compact(near.root);root.add(near.root);}far.visible=false;near.root.visible=true;return true;};return{root,setFrame(next){frame={...next};root.position.set(next.x??0,next.y??0,next.z??0);root.rotation.y=next.yaw??0;},ensure,pin(){ensure();pins++;let released=false;return()=>{if(released)return;released=true;pins=Math.max(0,pins-1);};},update(distance,{selected=true}={}){if(!alive)return;if(selected&&distance<=13||pins)ensure();else if((distance>22||!selected)&&near){near.dispose();near=null;far.visible=true;}root.visible=shown;},setVisible(value){shown=!!value;root.visible=shown;},snapshot:()=>({near:!!near,pins,far:far.visible}),dispose(){if(!alive)return;alive=false;near?.dispose();near=null;disposeToyTree(root);}};}
export function createMainHarborView(parent,localRoom){parent.userData.mainHarbor=true;parent.userData.mainIslandOverviewBounds={min:[-23,-.5,-16],max:[38,7,39]};const frameRoot=new T.Group();frameRoot.name='courtyard.harbor-frame';frameRoot.position.set(HARBOR_FRAME.x,HARBOR_FRAME.y,HARBOR_FRAME.z);frameRoot.rotation.y=HARBOR_FRAME.yaw;parent.add(frameRoot);const parked=parkedBoat(),dock=buildDock(frameRoot,BOAT_ENDPOINTS.villageHarbor,{boatFactory:()=>parked});compact(dock.root,n=>{if(n.name==='villageHarbor.pier.surface')return false;for(let p=n;p&&p!==dock.root;p=p.parent)if(p===parked.root)return false;return true;});dock.pin=()=>parked.pin();dock.setParkedVisible=value=>parked.setVisible(value);let disposed=false;return{frameRoot,dock,localRoom,context:{frameRoot,dock,localRoom,collisionWorld:()=>localRoom},prepare(){parked.ensure();},update(position,options){parked.update(Math.hypot(position.x-26.2,position.z-9.5),options);},snapshot:parked.snapshot,dispose(){if(disposed)return;disposed=true;dock.dispose();disposeToyTree(frameRoot);}};}
